/**
 * Nivo POS - Cloudflare R2 Upload Helper
 * File: src/lib/r2Upload.ts
 *
 * Reusable utility for direct, high-speed file uploads to Cloudflare R2
 * via presigned PUT URLs generated by /api/r2-upload-url.
 */

export type R2Folder = 'purchases' | 'sales' | 'products' | 'branding';

export interface UploadToR2Params {
  file: File;
  storeId: string;
  folder: R2Folder;
}

export interface UploadToR2Result {
  fileKey: string;
  publicUrl: string;
}

/**
 * Uploads a file directly to Cloudflare R2 using a server-presigned PUT URL.
 *
 * @param params { file, storeId, folder }
 * @returns Promise<{ fileKey: string; publicUrl: string }>
 */
export async function uploadToR2({
  file,
  storeId,
  folder,
}: UploadToR2Params): Promise<UploadToR2Result> {
  const contentType = file.type || 'application/octet-stream';

  // 1. Request presigned PUT URL from /api/r2-upload-url
  const presignRes = await fetch('/api/r2-upload-url', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      fileName: file.name,
      contentType,
      storeId,
      folder,
    }),
  });

  if (!presignRes.ok) {
    const errData = await presignRes.json().catch(() => null);
    throw new Error(
      errData?.error || `Failed to get R2 presigned upload URL (HTTP ${presignRes.status})`
    );
  }

  const presignData = await presignRes.json();
  const uploadUrl: string = presignData.uploadUrl || presignData.url;
  const fileKey: string = presignData.fileKey || presignData.key;
  const publicUrl: string = presignData.publicUrl || uploadUrl.split('?')[0];

  if (!uploadUrl || !fileKey) {
    throw new Error('R2 Presign response missing upload URL or fileKey');
  }

  // 2. Direct PUT upload of file to Cloudflare R2
  const r2UploadRes = await fetch(uploadUrl, {
    method: 'PUT',
    headers: {
      'Content-Type': contentType,
    },
    body: file,
  });

  if (!r2UploadRes.ok) {
    throw new Error(`Direct Cloudflare R2 PUT upload failed (HTTP ${r2UploadRes.status})`);
  }

  return {
    fileKey,
    publicUrl,
  };
}
